const body = $input.first().json.body;
const codeSnippet = body.codeSnippet || '';
const language = body.language || 'javascript';
const geminiKey = body.geminiApiKey;

const prompt = `Bạn là Senior QA Automation Engineer.\nHãy viết bộ kiểm thử Unit Test (Jest cho JavaScript hoặc PyTest cho Python) có độ bao phủ 100% (Positive, Negative, Boundary Cases) cho đoạn code sau:\n\n${codeSnippet}\n\nBẮT BUỘC chỉ trả về JSON thuần túy:\n{\n  "framework": "Jest",\n  "testCode": "test code string",\n  "testCasesCount": 4\n}`;

return {
  json: {
    geminiKey,
    requestBody: {
      contents: [{ role: "user", parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.2, responseMimeType: "application/json" }
    }
  }
};

const response = $input.first().json;
let raw = response.candidates[0].content.parts[0].text;
raw = raw.replace(/```json/gi, '').replace(/```/gi, '').trim();
const parsed = JSON.parse(raw);
return { json: { success: true, data: parsed } };
